#!/usr/bin/env node
// Deterministic generator for `pion/station-main/packages/station_ops/src/i18n_catalog.pion`
// from `client/i18n/catalog/{zh,en}/station.json` and `client/i18n/brand.ts`.
//
// Usage:
//   node pion/station-main/scripts/gen-i18n.mjs          # write generated file
//   node pion/station-main/scripts/gen-i18n.mjs --check  # exit 0 if up to date, 1 if drifted

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const MAIN_DIR = resolve(SCRIPT_DIR, "..");
const ROOT = resolve(MAIN_DIR, "../..");

const ZH_PATH = resolve(ROOT, "client/i18n/catalog/zh/station.json");
const EN_PATH = resolve(ROOT, "client/i18n/catalog/en/station.json");
const BRAND_PATH = resolve(ROOT, "client/i18n/brand.ts");
const OUT_PATH = resolve(MAIN_DIR, "packages/station_ops/src/i18n_catalog.pion");

function pionStr(s) {
  let out = '"';
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    const code = s.charCodeAt(i);
    if (ch === "\\") out += "\\\\";
    else if (ch === '"') out += '\\"';
    else if (ch === "\n") out += "\\n";
    else if (ch === "\r") out += "\\r";
    else if (ch === "\t") out += "\\t";
    else if (code < 0x20) out += `\\u{${code.toString(16)}}`;
    else out += ch;
  }
  out += '"';
  return out;
}

function parseBrand(src) {
  const stillfailMatch = /export\s+const\s+STILLFAIL\s*:\s*Product\s*=\s*\{\s*name:\s*"([^"]+)",\s*test:\s*"([^"]+)",\s*id:\s*"([^"]+)",\s*reverse:\s*"([^"]+)"\s*\}/.exec(src);
  if (!stillfailMatch) {
    throw new Error(`gen-i18n.mjs: failed to parse STILLFAIL from ${BRAND_PATH}`);
  }
  const stillfail = {
    name: stillfailMatch[1],
    test: stillfailMatch[2],
    id: stillfailMatch[3],
    reverse: stillfailMatch[4],
  };

  const products = [];
  const blockMatch = /export\s+const\s+PRODUCTS[^=]*=\s*\[([\s\S]*?)\];/.exec(src);
  if (!blockMatch) {
    throw new Error(`gen-i18n.mjs: failed to parse PRODUCTS from ${BRAND_PATH}`);
  }
  const entryRe = /\{\s*zones:\s*\[([^\]]*)\],\s*product:\s*\{\s*name:\s*"([^"]+)",\s*test:\s*"([^"]+)",\s*id:\s*"([^"]+)",\s*reverse:\s*"([^"]+)"\s*\}\s*\}/g;
  let m;
  while ((m = entryRe.exec(blockMatch[1])) !== null) {
    const zones = [];
    const zoneRe = /"([^"]+)"/g;
    let zm;
    while ((zm = zoneRe.exec(m[1])) !== null) {
      zones.push(zm[1]);
    }
    products.push({
      zones,
      product: { name: m[2], test: m[3], id: m[4], reverse: m[5] },
    });
  }
  return { stillfail, products };
}

function formatEntry(val) {
  if (typeof val === "string") {
    return `Some(CatalogEntry::Plain(${pionStr(val)}))`;
  }
  if (val && typeof val === "object" && typeof val.other === "string") {
    const oneExpr = typeof val.one === "string" ? `Some(${pionStr(val.one)})` : "None";
    return `Some(CatalogEntry::Plural(${oneExpr}, ${pionStr(val.other)}))`;
  }
  throw new Error(`gen-i18n.mjs: unsupported catalog entry: ${JSON.stringify(val)}`);
}

function emitLookupFn(name, dict) {
  const keys = Object.keys(dict).sort();
  const lines = [];
  lines.push(`pub fn ${name}(key : String) -> Option[CatalogEntry] {`);
  lines.push(`  match key {`);
  for (const k of keys) {
    lines.push(`    ${pionStr(k)} => ${formatEntry(dict[k])}`);
  }
  lines.push(`    _ => None`);
  lines.push(`  }`);
  lines.push(`}`);
  return lines.join("\n");
}

function generate() {
  const zh = JSON.parse(readFileSync(ZH_PATH, "utf8"));
  const en = JSON.parse(readFileSync(EN_PATH, "utf8"));
  const brandSrc = readFileSync(BRAND_PATH, "utf8");
  const { stillfail, products } = parseBrand(brandSrc);

  const lines = [];
  lines.push("// Code generated by `node pion/station-main/scripts/gen-i18n.mjs`. DO NOT EDIT.");
  lines.push("// Sources: `client/i18n/catalog/{zh,en}/station.json` and `client/i18n/brand.ts`.");
  lines.push("");
  lines.push("pub enum CatalogEntry {");
  lines.push("  Plain(String)");
  lines.push("  Plural(Option[String], String)");
  lines.push("}");
  lines.push("");
  lines.push("pub struct Product {");
  lines.push("  pub name : String");
  lines.push("  pub test_domain : String");
  lines.push("  pub id : String");
  lines.push("  pub reverse : String");
  lines.push("}");
  lines.push("");
  lines.push("pub struct ProductZones {");
  lines.push("  pub zones : Array[String]");
  lines.push("  pub product : Product");
  lines.push("}");
  lines.push("");
  lines.push("pub fn stillfail_product() -> Product {");
  lines.push("  Product::{");
  lines.push(`    name: ${pionStr(stillfail.name)},`);
  lines.push(`    test_domain: ${pionStr(stillfail.test)},`);
  lines.push(`    id: ${pionStr(stillfail.id)},`);
  lines.push(`    reverse: ${pionStr(stillfail.reverse)},`);
  lines.push("  }");
  lines.push("}");
  lines.push("");
  lines.push("pub fn branded_products() -> Array[ProductZones] {");
  lines.push("  [");
  for (const p of products) {
    const zonesLit = p.zones.map(pionStr).join(", ");
    lines.push("    ProductZones::{");
    lines.push(`      zones: [${zonesLit}],`);
    lines.push("      product: Product::{");
    lines.push(`        name: ${pionStr(p.product.name)},`);
    lines.push(`        test_domain: ${pionStr(p.product.test)},`);
    lines.push(`        id: ${pionStr(p.product.id)},`);
    lines.push(`        reverse: ${pionStr(p.product.reverse)},`);
    lines.push("      },");
    lines.push("    },");
  }
  lines.push("  ]");
  lines.push("}");
  lines.push("");
  lines.push(`pub let CATALOG_ZH_COUNT : Int = ${Object.keys(zh).length}`);
  lines.push(`pub let CATALOG_EN_COUNT : Int = ${Object.keys(en).length}`);
  lines.push("");
  lines.push(emitLookupFn("catalog_zh", zh));
  lines.push("");
  lines.push(emitLookupFn("catalog_en", en));
  lines.push("");

  return lines.join("\n");
}

const checkMode = process.argv.includes("--check");
const generated = generate();

if (checkMode) {
  if (!existsSync(OUT_PATH)) {
    console.error(`gen-i18n.mjs --check: missing ${OUT_PATH}`);
    process.exit(1);
  }
  const actual = readFileSync(OUT_PATH, "utf8");
  if (actual !== generated) {
    console.error(`gen-i18n.mjs --check: ${OUT_PATH} is out of date; run \`node pion/station-main/scripts/gen-i18n.mjs\``);
    process.exit(1);
  }
  process.exit(0);
}

mkdirSync(dirname(OUT_PATH), { recursive: true });
writeFileSync(OUT_PATH, generated, "utf8");
